SubProceso Potencia(base Como Entero, exponente Como Entero) Como Entero
    Si exponente = 0 Entonces
        Retornar 1;
    SiNo
        Retornar base * Potencia(base, exponente - 1);
    FinSi
FinSubProceso

Proceso CalcularFibonacci
    Definir n Como Entero;
    Leer n;
    Escribir Potencia(n, 2);
FinProceso
